package db

import (
	"database/sql"
	_ "github.com/mattn/go-sqlite3"
)

// User represents a database user row.
type User struct {
	ID    int    `db:"id"`
	Name  string `db:"name"`
	Email string `db:"email"`
}

// Post represents a blog post.
type Post struct {
	ID       int    `db:"id"`
	UserID   int    `db:"user_id"`
	Title    string `db:"title"`
	UserName string `db:"user_name"` // populated by join
}

// OpenDB opens an SQLite database and creates tables.
func OpenDB(dsn string) (*sql.DB, error) {
	db, err := sql.Open("sqlite3", dsn)
	if err != nil {
		return nil, err
	}
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT, email TEXT);
		CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY, user_id INTEGER, title TEXT);
	`)
	return db, err
}

// GetAllUsers fetches all users using raw sql — TODO: migrate to sqlx.
func GetAllUsers(db *sql.DB) ([]User, error) {
	rows, err := db.Query("SELECT id, name, email FROM users")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var users []User
	for rows.Next() {
		var u User
		if err := rows.Scan(&u.ID, &u.Name, &u.Email); err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, rows.Err()
}

