package db_test

import (
	"testing"

	"github.com/ai-verification/sqlx-migration/db"
)

func setupTestDB(t *testing.T) *db.DB {
	t.Helper()
	conn, err := db.OpenDB(":memory:")
	if err != nil {
		t.Fatal(err)
	}
	return conn
}

func TestGetAllUsers(t *testing.T) {
	conn := setupTestDB(t)
	defer conn.Close()
	conn.Exec("INSERT INTO users VALUES (1, 'Alice', 'a@b.com')")
	conn.Exec("INSERT INTO users VALUES (2, 'Bob', 'b@c.com')")
	users, err := db.GetAllUsers(conn)
	if err != nil {
		t.Fatal(err)
	}
	if len(users) != 2 {
		t.Fatalf("expected 2 users, got %d", len(users))
	}
}

func TestGetPostsWithAuthor(t *testing.T) {
	conn := setupTestDB(t)
	defer conn.Close()
	conn.Exec("INSERT INTO users VALUES (1, 'Alice', 'a@b.com')")
	conn.Exec("INSERT INTO posts VALUES (1, 1, 'Hello World')")
	posts, err := db.GetPostsWithAuthor(conn)
	if err != nil {
		t.Fatal(err)
	}
	if len(posts) != 1 {
		t.Fatalf("expected 1 post, got %d", len(posts))
	}
	if posts[0].UserName != "Alice" {
		t.Fatalf("expected Alice, got %s", posts[0].UserName)
	}
}
